:root {
  --bg: #1e1b2e;
  --card-bg: #2d2a45;
  --text: #f0edf7;
  --accent: #f5a623;
  --accent-hover: #ffbf4d;
  --error: #ff6b6b;
  --border: #4a4668;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 32px 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 8px;
  color: var(--accent);
}

.subtitle {
  font-size: 1rem;
  margin-bottom: 24px;
  opacity: 0.85;
}

.field {
  margin-bottom: 16px;
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: 4px;
}

input {
  width: 100%;
  padding: 12px 14px;
  font-size: 1rem;
  font-family: inherit;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  color: var(--text);
  transition: border-color 0.2s;
}

input:hover {
  border-color: var(--accent);
}

input:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
  border-color: var(--accent);
}

button {
  width: 100%;
  padding: 14px;
  font-size: 1.125rem;
  font-weight: 700;
  font-family: inherit;
  color: var(--bg);
  background: var(--accent);
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

button:hover {
  background: var(--accent-hover);
}

button:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 3px;
}

button:active {
  transform: scale(0.98);
}

.result {
  margin-top: 24px;
  padding-top: 24px;
  border-top: 2px solid var(--border);
}

.result h2 {
  font-size: 1.25rem;
  margin-bottom: 12px;
}

#change-amount {
  color: var(--accent);
}

.breakdown {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.breakdown li {
  display: flex;
  justify-content: space-between;
  padding: 8px 12px;
  background: var(--bg);
  border-radius: 6px;
  font-size: 1rem;
}

.breakdown .denom {
  font-weight: 600;
}

.breakdown .count {
  color: var(--accent);
  font-weight: 700;
}

.error {
  margin-top: 16px;
  color: var(--error);
  font-weight: 600;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
}

(function () {
  'use strict';

  const DENOMINATIONS = [2000, 1000, 500, 200, 100, 50, 20, 10, 5]; // in cents
  const DENOM_LABELS = ['€20', '€10', '€5', '€2', '€1', '€0.50', '€0.20', '€0.10', '€0.05'];

  const form = document.getElementById('change-form');
  const priceInput = document.getElementById('price');
  const paidInput = document.getElementById('paid');
  const resultDiv = document.getElementById('result');
  const changeAmountSpan = document.getElementById('change-amount');
  const breakdownList = document.getElementById('change-breakdown');
  const errorP = document.getElementById('error');

  function toCents(value) {
    return Math.round(parseFloat(value) * 100);
  }

  function formatEuro(cents) {
    return '€' + (cents / 100).toFixed(2);
  }

  function showError(message) {
    errorP.textContent = message;
    errorP.hidden = false;
    resultDiv.hidden = true;
  }

  function clearError() {
    errorP.hidden = true;
    errorP.textContent = '';
  }

  function calculateChange(priceCents, paidCents) {
    let changeCents = paidCents - priceCents;
    if (changeCents < 0) {
      showError('Amount paid must be at least the price.');
      return null;
    }
    if (changeCents === 0) {
      return { changeCents: 0, breakdown: [] };
    }

    const breakdown = [];
    for (let i = 0; i < DENOMINATIONS.length; i++) {
      const denom = DENOMINATIONS[i];
      const count = Math.floor(changeCents / denom);
      if (count > 0) {
        breakdown.push({ label: DENOM_LABELS[i], count });
        changeCents -= count * denom;
      }
    }
    return { changeCents: paidCents - priceCents, breakdown };
  }

  function renderResult(changeCents, breakdown) {
    changeAmountSpan.textContent = formatEuro(changeCents);
    breakdownList.innerHTML = '';
    if (breakdown.length === 0) {
      const li = document.createElement('li');
      li.textContent = 'No change needed.';
      breakdownList.appendChild(li);
    } else {
      breakdown.forEach(function (item) {
        const li = document.createElement('li');
        const denomSpan = document.createElement('span');
        denomSpan.className = 'denom';
        denomSpan.textContent = item.label;
        const countSpan = document.createElement('span');
        countSpan.className = 'count';
        countSpan.textContent = '× ' + item.count;
        li.appendChild(denomSpan);
        li.appendChild(countSpan);
        breakdownList.appendChild(li);
      });
    }
    resultDiv.hidden = false;
    clearError();
  }

  form.addEventListener('submit', function (event) {
    event.preventDefault();
    clearError();

    const priceVal = priceInput.value.trim();
    const paidVal = paidInput.value.trim();

    if (priceVal === '' || paidVal === '') {
      showError('Please enter both the price and the amount paid.');
      return;
    }

    const priceCents = toCents(priceVal);
    const paidCents = toCents(paidVal);

    if (isNaN(priceCents) || isNaN(paidCents)) {
      showError('Please enter valid numbers.');
      return;
    }
    if (priceCents < 0 || paidCents < 0) {
      showError('Amounts cannot be negative.');
      return;
    }

    const result = calculateChange(priceCents, paidCents);
    if (result) {
      renderResult(result.changeCents, result.breakdown);
    }
  });

  // Clear result when inputs change
  [priceInput, paidInput].forEach(function (input) {
    input.addEventListener('input', function () {
      resultDiv.hidden = true;
      clearError();
    });
  });
})();
